raw_text:
{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "ཇི་སྐད་དུ།",
      "head": "རྣམ་པར་དབྱེ་བ་གཞུང་ཡིན་ཏེ། །\nགནད་དུ་བསྡུས་པ་མན་ངག་ཡིན། །",
      "tail": "གནད་དུ་བསྡུས་པ་མན་ངག་ཡིན། །"
    },
    {
      "label": "QUOTE",
      "head": "ཁ་རྩང་ཕན་ཆད་བྲམ་ཟེ་མིན། །\nདེ་རིང་ཚུན་ཆད་བྲམ་ཟེ་ཡིན། །",
      "tail": "དེ་རིང་ཚུན་ཆད་བྲམ་ཟེ་ཡིན། །"
    },
    {
      "label": "QUOTE",
      "head": "བཅོམ་ལྡན་འདས་ཀྱི་སྲས་སྒྲ་གཅན་འཛིན་བཟང་པོ་ལ་རབ་ཏུ་བྱུང་ནས་ཤེས་བྱ་རིག་པའི་གནས་མཐའ་དག་ལ་མཁས་པའི་པཎྜི་ཏ་ཆེན་པོར་གྱུར་ཏེ། བྲམ་ཟེ་སྒྲ་གཅན་འཛིན་ཞེས་བྱ་བར་གྲགས་ཤིང་། སློབ་དཔོན་ཀླུ་སྒྲུབ་ལ་སོགས་པའི་མཁན་པོ་ཡང་མཛད་དོ། །",
      "tail": "མཁན་པོ་ཡང་མཛད་དོ། །"
    },
    {
      "label": "QUOTE",
      "head": "དེའི་ཚེ་ཡུལ་དེ་ན་རྒྱལ་པོ་མ་ཧཱ་ཕཱ་ལ་ཞེས་བྱ་བས་མཆོད་པའི་གནས་སུ་བཀུར་ཞིང་སྲི་ཞུ་དང་བཅས་ནས་གུས་པས་བསྟེན་ཏོ། །",
      "tail": "དང་བཅས་ནས་གུས་པས་བསྟེན་ཏོ། །"
    },
    {
      "label": "QUOTE",
      "head": "དུས་ནམ་ཞིག་གི་ཚེ་དཔལ་རྟ་མགྲིན་གང་ཟག་ཅིག་ཅར་བའི་རིགས་ཅན་འདུལ་བའི་ཕྱིར་དུ་བྱང་ཆུབ་སེམས་དཔའ་བློ་གྲོས་རིན་ཆེན་ཞེས་བྱ་བར་གྱུར་པ་དེས། བྲམ་ཟེ་ཆེན་པོའི་དོན་བྱ་བར་དགོངས་ནས་མདའ་མཁན་མ་ཞིག་ཏུ་སྤྲུལ་ཏེ་ཧེ་ཊེ་ཞེས་པ་བོད་སྐད་དུ་ཚོང་དུས་ཏེ་དེའི་དབུས་སུ་འདུག་གོ། །",
      "tail": "དབུས་སུ་འདུག་གོ། །"
    },
    {
      "label": "QUOTE",
      "head": "དུས་དེར་བྲམ་ཟེ་སྒྲ་གཅན་འཛིན་ལྗོངས་རྒྱུ་ཞིང་སྐྱོ་སངས་ལ་བྱོན་པས། ཚོང་དུས་དེའི་དབུས་ན་བུད་མེད་གཞོན་ནུ་མ་མདའ་འཆོས་ཤིང་གཡས་སུ་ཡང་མི་བལྟ། གཡོན་དུ་ཡང་མི་བལྟ་མ་ཡེངས་པར་མདའ་བྱེད་པ་གཅིག་གཟིགས་ནས་གམ་དུ་བྱོན་པ་ན། དེས་གཉུག་མ་ (སྨྱུག་མ་) ཚུགས་གསུམ་དང་ལྡན་པ་གཅིག་ལེགས་པར་བསྲོང་སྟེ་རྩ་བ་ནས་བཅད། རྩེ་མོ་ནས་ཀྱང་བཅད། རྩ་བ་དེ་ཁ་བཞིར་བཀས། དེ་ལ་མདེའུ་ཞིག་བསྐྱོན་ནས་དེ་རྒྱུས་པས་བཅིངས། རྩེ་མོ་དེ་ཁ་གཉིས་སུ་བཀས། དེ་ལ་སྒྲོ་བཞི་སྒྲོན། མིག་ཡ་གཅིག་བཙུམ་ཡ་གཅིག་བགྲད་ནས་མདའ་དེ་གཞན་ལ་བརྡེག་པའི་ཕྱིར་འདོམ་འགེངས་པའི་ཕྱག་རྒྱ་བྱེད་པ་གཟིགས་ནས། བུ་མོ་ཁྱོད་མདའ་མཁན་མ་ཡིན་ནམ་གསུངས་པ་ན། རིགས་ཀྱི་བུ་སངས་རྒྱས་ཀྱི་དགོངས་པ་ནི་བརྡ་དང་ཐབས་ཀྱིས་ཤེས་པར་ནུས་ཀྱིས་ཚིག་དང་ཡི་གེས་ཤེས་པ་མ་ཡིན་ནོ་ཞེས་ཟེར་ཏོ། །",
      "tail": "ཤེས་པ་མ་ཡིན་ནོ་ཞེས་ཟེར་ཏོ། །"
    },
    {
      "label": "QUOTE",
      "head": "དེར་མཁའ་འགྲོ་མའི་བརྡ་དོན་ཐུགས་ལ་འཁྲུངས་ཏེ། གཉུག་མ་๊སྨྱུག་མ་์ ནི་མ་བཅོས་པའི་བརྡ་དང་། ཚིགས་གསུམ་とལྡན་པ་དེ་སྐུ་གསུམ་མངོན་དུ་བྱེད་དགོས་པའི་བརྡོའོ། །སྲོང་བ་ནི་ལམ་སྲོང་བའི་བརྡ། རྩ་བ་ནས་བཅད་པ་འཁོར་བའི་གཞི་རྩ་གཅོད་དགོས་པའི་བརྡ། རྩེ་མོ་ནས་བཅད་པ་བདག་འཛིན་རྩད་ནས་གཅོད་དགོས་པའི་བརྡ། རྩ་བ་དེ་ཁ་བཞིར་བཀས་པ་དྲན་པ། དྲན་མེད། སྐྱེ་མེད། བློ་འདས་བཞིས་རྒྱས་འདེབས་དགོས་པའི་བརྡ། མདེའུ་བསྐྱོན་པ་དེ། དེ་ལ་ཤེས་རབ་ཀྱི་མདེའུ་བསྐྱོན་དགོས་པའི་བརྡ། དེ་རྒྱུས་པས་བཅིངས་པ་དེ། དེ་རྣམས་ཟུང་འཇུག་གི་ཕྱག་རྒྱས་འཆིང་དགོས་པའི་བརྡ། རྩེ་མོ་ཁ་གཉིས་སུ་བཀས་པ་ཐབས་དང་ཤེས་རབ་ཀྱི་བརྡ། སྒྲོ་བཞི་ལྟ་སྒོམ་སྤྱོད་འབྲས་བཞིའི་བརྡ། མིག་ཡ་གཅིག་ཕྱེ་ནས་ཅིག་ཤོས་བཙུམ་པ་རྣམ་ཤེས་ཀྱི་མིག་ཚུམ་ལ་ཡེ་ཤེས་ཀྱི་མིག་ཕྱེ་ཞེས་པའི་བརྡ། བརྡེག་པའི་ཕྱག་རྒྱ་དེ་གཉིས་འཛིན་གྱི་སྙིང་ལ་གཉིས་མེད་ཀྱི་མངའ་བསྣུན་དགོས་པའི་བརྡར་གོ་ནས་ཅིག་ཅར་དུ་གྲོལ་ཏེ། མཚན་ཡང་ས་ར་ཧ་ཞེས་བྱ་བར་ཐོགས་སོ། །",
      "tail": "མཚན་ཡང་ས་ར་ཧ་ཞེས་བྱ་བར་ཐོགས་སོ། །"
    },
    {
      "label": "QUOTE",
      "head": "དེ་ཡང་རྒྱ་གར་ལྷོ་ཕྱོགས་པའི་སྐད་དུ་ས་པ་ར་ནི་མདའ་དང་། ཧ་ཧ་ཏ་ནི་བསྣུན་པ་ལ་འཇུག་པས་གཟུང་འཛིན་གྱི་སྙིང་ལ་གཉིས་མེད་ཀྱི་མདའ་བསྣུན་པས་ན་མདའ་བསྣུན་ཞེས་གྲགས་སོ། །",
      "tail": "མདའ་བསྣུན་ཞེས་གྲགས་སོ། །"
    },
    {
      "label": "QUOTE",
      "head": "དེར་ཁྱོད་མདའ་མཁན་མར་མི་འདུག་བརྡ་མཁན་མར་འདུག་གསུངས་ནས་དེ་དང་སྙོམས་པར་འཇུག་ཅིང་རྣལ་འབྱོར་གྱི་སྤྱོད་པ་ལ་ཞུགས་ཏེ།",
      "tail": "སྤྱོད་པ་ལ་ཞུགས་ཏེ།"
    },
    {
      "label": "QUOTE",
      "head": "དེའི་ཚེ་འཁོལ་མོ་རོ་ཟན་མས་ཚོགས་ཀྱི་འཁོར་ལོ་བསྐོར་བའི་ངོར་རྒྱན་གྱི་རྣམ་དག་རྡོ་རྗེའི་ཐོད་གླུ་གསུངས།",
      "tail": "ཐོད་གླུ་གསུངས།"
    },
    {
      "label": "QUOTE",
      "head": "བྲམ་ཟེ་སྒྲ་གཅན་འཛིན་བསྙེན་པར་རྫོགས་པའི་དཀའ་ཐུབ་ཀྱི་ངལ་བ་མ་བཟོད་པར་ཚངས་སྤྱོད་ལས་ཉམས་ནས་རིགས་ངན་གྱི་ཆུང་མ་དང་བཅས་ཏེ། དམན་པའི་སྤྱོད་པས་ཕྱོགས་མཐར་ཁྱི་བཞིན་དུ་འཁྱམ་པར་གྱུར་ཏོ། །ཞེས་ཀུན་ནས་ཀུན་ཏུ་གླེང་སློང་བར་གྱུར་པས་རྒྱལ་པོ་མ་ཧཱ་ཕཱ་ལས་གསན་ནས། མངའ་རིས་ཀྱི་འབངས་ཕལ་པ་རྣམས་ལ་བཀའ་བསྒོས་ཏེ། བྲམ་ཟེ་ཆེན་པོ་ལ་ངན་པའི་སྤྱོད་པ་ལས་བཟློག་ཅིང་ཚངས་པར་སྤྱོད་པའི་སྒོ་ནས་རྒྱལ་པོའི་ཁབ་ལ་སོགས་པར་སྐྱེ་དགུའི་དོན་མཛད་པར་གསོལ་བ་འདེབས་སུ་བསྩལ་བའི་དུས་སུ། འབངས་ཕལ་པ་རྣམས་ཀྱི་ངོར་དོ་ཧ་བརྒྱ་དྲུག་ཅུ་པ་མགུར་དུ་བཞེངས་ནས་དེ་རྣམས་ཡང་དག་པའི་ལམ་ལ་འཛུད་པར་མཛད་དོ། །",
      "tail": "ལམ་ལ་འཛུད་པར་མཛད་དོ། །"
    },
